validator.c:script:
import io.nop.api.core.exceptions.NopException;
import io.nop.excel.ExcelErrors;
import io.nop.commons.util.NetHelper;

if(!NetHelper.isIpV4Address(value)) {
    throw new NopException(ExcelErrors.ERR_IMPORT_FIELD_VALUE_VALIDATE_FAIL)
        .param("errorDesc", "IP地址格式不正确,应为标准IPv4格式(如192.168.1.1),当前输入值:" + value);
}

import io.nop.api.core.exceptions.NopException;
import io.nop.excel.ExcelErrors;

// 唯一性校验
const devices = record.devices;
const ipAddrSet = new Set();
const deviceIdSet = new Set();
const nameSet = new Set();

for(let device of devices) {
    if(ipAddrSet.contains(device.ipAddr)) {
        throw new NopException(ExcelErrors.ERR_IMPORT_FIELD_VALUE_VALIDATE_FAIL)
                                .param("errorDesc", "IP地址字段重复值：" + device.ipAddr);
    }

    if(deviceIdSet.contains(device.deviceId)) {
        throw new NopException(ExcelErrors.ERR_IMPORT_FIELD_VALUE_VALIDATE_FAIL)
                                .param("errorDesc", "设备编号字段重复值：" + device.deviceId);
    }

    if(nameSet.contains(device.name)) {
        throw new NopException(ExcelErrors.ERR_IMPORT_FIELD_VALUE_VALIDATE_FAIL)
                                .param("errorDesc", "设备名称字段重复值：" + device.name);
    }

    ipAddrSet.add(device.ipAddr);
    deviceIdSet.add(device.deviceId);
    nameSet.add(device.name);
}
